jsonSchema:
{
  "type": {
    "type": "string",
    "description": "반드시 허용된 30개 action type 중 하나. 전체 문법과 필수/선택 필드는 system prompt와 flowise-output.schema.json 참조."
  },
  "id": {
    "type": "string",
    "optional": true,
    "description": "context에 존재하는 장소·업체·방문·저장 여행 ID. 행동에 맞는 종류를 사용한다."
  },
  "saved": {
    "type": "boolean",
    "optional": true,
    "description": "bookmark 전용. true 찜, false 찜 해제."
  },
  "stage": {
    "type": "string",
    "optional": true,
    "description": "show 전용. discover|place|food|stay|plan|saved|route|directions|progress|external|compare|budget|check|detail|library|history|help|answer"
  },
  "kind": {
    "type": "string",
    "optional": true,
    "description": "show 전용. 식당|카페"
  },
  "day": {
    "type": "number",
    "optional": true,
    "description": "day/transfer 필수, show/add-entity 선택. 1~3 정수이며 현재 여행에 존재하는 DAY."
  },
  "region": {
    "type": "string",
    "optional": true,
    "description": "region 전용. 제주|서울"
  },
  "value": {
    "type": "any",
    "optional": true,
    "description": "walk는 1~20 정수; stay-budget은 1~1000000 정수; cuisine는 전체|한식|양식 문자열."
  },
  "savedOnly": {
    "type": "boolean",
    "optional": true,
    "description": "build 전용. true이면 찜한 장소로 초안."
  },
  "direction": {
    "type": "number",
    "optional": true,
    "description": "move 전용. -1 또는 1."
  },
  "placeId": {
    "type": "string",
    "optional": true,
    "description": "directions 장소 ID. id/businessId와 함께 넣지 않는다."
  },
  "businessId": {
    "type": "string",
    "optional": true,
    "description": "directions 업체 ID. id/placeId와 함께 넣지 않는다."
  },
  "status": {
    "type": "string",
    "optional": true,
    "description": "progress 전용. done|skipped|pending"
  },
  "ids": {
    "type": "array",
    "optional": true,
    "description": "compare 전용. 서로 다른 알려진 ID 문자열 2~3개. 조건에 맞는 같은 종류의 후보."
  },
  "people": {
    "type": "number",
    "optional": true,
    "description": "budget 전용. 1~20 정수."
  },
  "rooms": {
    "type": "number",
    "optional": true,
    "description": "budget 전용. 1~10 정수."
  },
  "days": {
    "type": "number",
    "optional": true,
    "description": "configure 전용. 1~3 정수."
  },
  "theme": {
    "type": "string",
    "optional": true,
    "description": "configure 전용. all|sea|green"
  },
  "foodBudget": {
    "type": "any",
    "optional": true,
    "description": "configure 전용. 1~1000000 정수 또는 null."
  },
  "booked": {
    "type": "boolean",
    "optional": true,
    "description": "configure 전용. 사용자가 이미 예약한 숙소가 있다고 한 사실을 반영."
  },
  "meals": {
    "type": "boolean",
    "optional": true,
    "description": "configure 전용. 식사 포함."
  },
  "cafes": {
    "type": "boolean",
    "optional": true,
    "description": "configure 전용. 카페 포함."
  },
  "lodging": {
    "type": "boolean",
    "optional": true,
    "description": "configure 전용. 숙소 포함."
  }
}
